<form method="GET" class="mt-6 grid gap-3 rounded border border-white/10 bg-[var(--color-bg-secondary)] p-4 sm:grid-cols-2 lg:grid-cols-5" aria-label="Filtros de reporte"><label class="text-sm">Desde<input type="date" name="from" value="{{ request('from') }}" class="mt-1 min-h-11 w-full rounded bg-black/20 px-3"></label><label class="text-sm">Hasta<input type="date" name="to" value="{{ request('to') }}" class="mt-1 min-h-11 w-full rounded bg-black/20 px-3"></label><label class="text-sm">Periodo<select name="period" class="mt-1 min-h-11 w-full rounded bg-black/20 px-3"><option value="30">Últimos 30 días</option><option value="7">Últimos 7 días</option><option value="current_month">Mes actual</option><option value="current_year">Año actual</option></select></label><label class="text-sm">Servicio<select name="service" class="mt-1 min-h-11 w-full rounded bg-black/20 px-3"><option value="">Todos</option><option value="design">Diseño</option><option value="video">Video</option><option value="render">Render 3D</option></select></label><button class="min-h-11 self-end rounded bg-white/10 px-4 py-3 font-semibold">Aplicar filtros</button></form>
